-- Student Management System - reference PostgreSQL schema
--
-- The app creates these tables automatically through EF Core migrations,
-- so you normally do NOT need to run this file. It exists so you can:
--   * read the table design at a glance (good for interviews), and
--   * create the tables by hand if you prefer SQL over migrations.
-- Use ONE approach only (migrations OR this file), not both.

CREATE TABLE "Admins" (
    "Id"           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Username"     varchar(50)  NOT NULL,
    "PasswordHash" varchar(100) NOT NULL          -- BCrypt hash, never the real password
);
CREATE UNIQUE INDEX "IX_Admins_Username" ON "Admins" ("Username");

CREATE TABLE "Departments" (
    "Id"   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(100) NOT NULL
);
CREATE UNIQUE INDEX "IX_Departments_Name" ON "Departments" ("Name");

CREATE TABLE "Courses" (
    "Id"           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name"         varchar(100) NOT NULL,
    "DepartmentId" integer NOT NULL REFERENCES "Departments" ("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX "IX_Courses_DepartmentId_Name" ON "Courses" ("DepartmentId", "Name");

CREATE TABLE "Students" (
    "Id"             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentCode"    varchar(20)  NOT NULL,       -- e.g. STU0001
    "FullName"       varchar(100) NOT NULL,
    "Email"          varchar(150) NOT NULL,
    "PhoneNumber"    varchar(20)  NOT NULL,
    "CourseId"       integer NOT NULL REFERENCES "Courses" ("Id") ON DELETE RESTRICT,
    "EnrollmentDate" date NOT NULL,
    "CreatedAt"      timestamp with time zone NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "IX_Students_StudentCode" ON "Students" ("StudentCode");
CREATE UNIQUE INDEX "IX_Students_Email" ON "Students" ("Email");
CREATE INDEX "IX_Students_CourseId" ON "Students" ("CourseId");
